function manualReview(): CatalogReview {
  const item = catalogReview();
  item.analysis = { ...item.analysis, state: 'idle', generation: 0, operationId: null, completedChunks: 0, totalChunks: 0, attemptsUsed: 0 };
  item.suggestions = [];
  item.source.album.title = item.source.tracks[0].title = 'Shared synthetic name';
  item.draft.album.title = 'Manual Album correction';
  item.draft.tracks[0].title = 'Manual track correction';
  return item;
}
/** The format-3 review after its lookup, with the guest identity answered so nothing waits. */
function lookedUp() {
  const item = reviewAfterLookup(capturedCatalogReview()), identity = reviewIdentityResponse();
  identity.identities[0] = { ...identity.identities[0], needsAnswer: false, decision: { scope: 'artist', identity: guestHandle, boundName: 'Synthetic guest', boundMusicBrainzId: null,
    action: 'create-distinct', candidateId: null, candidateRevision: null } };
  return { item, identity, lookup: reviewLookupResponse() };
}

/**
 * Renders the step with `choices`, each an explicit choice made on its item's current basis; the summary and identity reads answer
 * `lookup` and `identity` (a function may answer each read differently).
 */
function mount(item: CatalogReview, { choices = {}, lookup, identity }: { choices?: Record<string, boolean>; lookup?: ReviewLookupResponse;
  identity?: ReviewIdentityResponse | (() => Response | Promise<Response>) } = {}) {
  const { items } = reviewApplyModel({ item, lookup: lookup?.lookup ?? null, summary: null, waiting: null, identity: typeof identity === 'object' ? identity : null, choices: {} });
  const chosen = (checked: Record<string, boolean>) => Object.fromEntries(Object.entries(checked).map(([key, value]) => [key, { checked: value, basis: items.find(entry => entry.key === key)?.basis ?? '' }]));
  const onChoose = vi.fn(), onConfirm = vi.fn(), client = new QueryClient({ defaultOptions: { queries: { retry: false } } }), reads: string[] = [];
  client.setQueryData(['browser-session'], session);
  vi.stubGlobal('fetch', vi.fn(async (path: string) => {
    reads.push(path);
    if (path.endsWith('/lookup')) return lookup ? reviewJson(lookup) : reviewJson({ code: 'unexpected' }, 500);
    return typeof identity === 'function' ? identity() : identity ? reviewJson(identity) : reviewJson({ code: 'unexpected' }, 500);
  }));
  const element = (value: Record<string, boolean>) => <QueryClientProvider client={client}><CatalogReviewApply item={item} choices={chosen(value)} disabled={false} onChoose={onChoose} onConfirm={onConfirm} /></QueryClientProvider>;
  const view = render(element(choices));
  return { onChoose, onConfirm, reads, choose: (value: Record<string, boolean>) => view.rerender(element(value)) };
}
const box = (name: string) => screen.findByRole('checkbox', { name });
const card = async (name: string) => within((await box(name)).closest('article')!);

test('manual saved differences identify the original values and distinguish an Album from a same-named track without Luna or any read', async () => {
  const item = manualReview(), { onChoose, reads } = mount(item);
  const album = await box('Update Album · Shared synthetic name · Title'), track = await box('Update Track · Shared synthetic name · Title');
  expect(within(album.closest('article')!).getByText('Original Album information')).toBeVisible();
  expect(within(album.closest('article')!).getByText('Value to apply')).toBeVisible();
  expect(within(album.closest('article')!).getByText('Manual Album correction')).toBeVisible();
  expect(within(track.closest('article')!).getByText('Manual track correction')).toBeVisible();
  expect([album, track].map(input => (input as HTMLInputElement).checked)).toEqual([false, false]);
  expect(screen.queryByText('When Luna AI ran')).not.toBeInTheDocument();
  expect(screen.getByRole('button', { name: 'Update original Album (0)' })).toBeDisabled();
  fireEvent.click(track);
  expect(onChoose).toHaveBeenCalledWith(`track:${slotId}:title`, { checked: true, basis: JSON.stringify(['Shared synthetic name', 'Manual track correction']) });
  // A review not captured for lookup has nothing to read.
  expect(reads).toEqual([]);
});

