test('a looked-up review lists every change with its default, the member line, identities and what it sends', async () => {
  const { item, identity, lookup } = lookedUp();
  identity.identities[1] = { ...identity.identities[1], musicBrainzIdWrite: { scope: 'artist', identity: leadHandle, musicBrainzId: '00000000-0000-4000-8000-0000000000a1', replaces: null } };
  identity.musicBrainzIds = [identity.identities[1].musicBrainzIdWrite!];
  const { onConfirm, reads } = mount(item, { lookup, identity });
  const artists = await card('Update Album · Synthetic catalog Album · Artists');
  // Review-only items and lookup-filled values arrive selected; a value with an open conflict cannot be selected.
  expect(await box('Update Album · Synthetic catalog Album · Artists')).toBeChecked();
  expect(artists.getByText('Synthetic catalog Artist')).toBeVisible();
  expect(artists.getByText('Synthetic catalog Artist feat. Synthetic guest')).toBeVisible();
  expect(within((await box('Update Album · Synthetic catalog Album · Expected tracklist')).closest('article')!).getByText('3 rows, 1 without a file')).toBeVisible();
  expect(screen.getByText('No expected tracklist')).toBeVisible();
  expect(screen.getByRole('checkbox', { name: 'Update Track · Synthetic second track · Track number' })).toBeChecked();
  const date = screen.getByRole('checkbox', { name: 'Update Album · Synthetic catalog Album · Release date' });
  expect([date.matches(':checked'), date.matches(':disabled')]).toEqual([false, true]);
  expect(date).toHaveAccessibleDescription('Answer its lookup conflict first');
  // The member stored as Unknown gains its own track's artist and becomes documented.
  const member = await card('Update Track · Synthetic second track · Artists');
  expect(screen.getByRole('checkbox', { name: 'Update Track · Synthetic second track · Artists' })).toBeChecked();
  expect(member.getByText('—')).toBeVisible();
  expect(member.getByText('Synthetic guest')).toBeVisible();
  expect(member.getByText('This track\'s Artist credits will be marked Documented (currently Unknown).')).toBeVisible();
  // The identities the selection owns: the lead reused (hidden) recording its ID, the guest created.
  const lines = within(screen.getByRole('heading', { name: 'Artists and label' }).closest('section')!);
  expect(lines.getByText('Reuses the existing Synthetic catalog Artist · Visibility: Hidden')).toBeVisible();
  expect(lines.getByText('Records MusicBrainz ID 00000000-0000-4000-8000-0000000000a1')).toBeVisible();
  expect(lines.getByText('Creates Synthetic guest as new')).toBeVisible();
  fireEvent.click(screen.getByRole('button', { name: 'Update original Album (4)' }));
  const sent = onConfirm.mock.calls[0][0] as ReviewApplySelection;
  expect([sent.fields, sent.memberCredits, sent.musicBrainzIds]).toEqual([[{ scope: 'album', slotId: null, field: 'artists' }, { scope: 'album', slotId: null, field: 'expectedTracklist' },
    { scope: 'track', slotId: slotTwo, field: 'trackNumber' }], [slotTwo], identity.musicBrainzIds]);
  expect(reads.filter(path => path.endsWith('/lookup')).length + reads.filter(path => path.endsWith('/candidates')).length).toBe(2);
});

